------------ import ------------
local UIEventProxy = CS.Engine.UI.UIEventProxy
local KTool = CS.Engine.Lib.KTool
------------ import ------------

------------ define ------------
local PrefabName1 = 'GoodNode'
local PrefabName2 = 'GoodNode'
local GoodsNodePath = "Game.Behaviours.GoodNodeMB"
------------ define ------------

---@class MatConvertDetail
---@field Text                          	UnityEngine.RectTransform               
---@field GoodNode                      	UnityEngine.RectTransform               
---@field View                          	UnityEngine.RectTransform               
---@field ListView                      	UnityEngine.RectTransform               
local MatConvertDetail = Class('MatConvertDetail')

function MatConvertDetail:__init()
    self.consume = nil
end

function MatConvertDetail:__delete()
    self.consume = nil
end

function MatConvertDetail:Awake()
    --local rayTran = self.controller.transform:Find('RayNode')
    UIEventProxy.Create(self.controller.transform.parent.gameObject).onPointerClick = function()
        KTool.SetActive(self.controller.transform.parent.gameObject, false)
    end
end

function MatConvertDetail:FillGoods()
    if not self.consume then
        return
    end
    for i = 1, #self.consume do
        local go = self.View.transform:Find("good"..i)
        if not go then
            go = KTool.Instantiate(self.View.gameObject, self.GoodNode.gameObject, false)
            go.name = "good"..i
        end
        self:FillGood(go, self.consume[i], i)
        KTool.SetActive(go, true)
    end
end

function MatConvertDetail:FillGood(go, data, ind)
    if not go or not data then
        return
    end
    local cell = go
    local goodNodeTran = cell.transform:Find("GoodNode")
    local v = data
    local gainVo = v.gainVo
    local consume = table.takeFirst(v.consume)
    local goodsId = consume.goodsId
    if goodNodeTran then
        local goodItemNodeMB = GetLuaBehaviour(goodNodeTran.gameObject, GoodsNodePath)
        if not isNull(goodItemNodeMB) then
            if isNull(goodItemNodeMB.Env) then
                goodItemNodeMB:Init()
            end
            local goodsNum = 0
            if ind == 1 then
                goodsNum = 1
                goodsId = gainVo.goodsId
            else
                goodsNum = self:GetBasicMultiplierByPosition(ind)
            end
            ---@type GoodNodeMB
            local goodItemNodeEnv = goodItemNodeMB.Env
            goodItemNodeEnv:Reload({
                goodsId = goodsId, isShowNo = true, text = string.format_color_tag(FormatCurrencyNum(goodsNum), "#4D4D4D")
            })
        end
    end

    if ind == #self.consume then
        KTool.SetActive(go.transform:Find("ImgArrow"), false)
    end
end

---GetBasicMultiplierByPosition
---获取基础的一阶的乘法系数
---@param position number
function MatConvertDetail:GetBasicMultiplierByPosition(position)
    ---前面所有的位置
    local multiply = 1
    for i = 2, position do
        ---前面所有的位置
        ---@type MatCompositeVo
        local preVo = self.consume[i]
        local consume = table.takeFirst(preVo.consume)
        multiply = multiply * checkNumber(consume.goodsNum)
    end
    return multiply
end

---FreshData
---消耗方式
---@param consume table
function MatConvertDetail:FreshData(consume)
    self.consume = consume
    self:FillGoods()
end

function MatConvertDetail:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return MatConvertDetail